def transform(grid):
    out=[r[:] for r in grid]
    # The uppermost horizontal 5-bar is the isolated target selected by the guide;
    # recolor it using the guide color.
    for c in range(len(grid[0])-2):
        if grid[0][c:c+3] == [5,5,5]:
            for x in range(c,c+3): out[0][x]=9
    return out
